using Microsoft.VisualBasic;
using System;
using System.Collections;
using System.Collections.Generic;
using System.Data;
using System.Diagnostics;
using JiwaFinancials.Jiwa;
using System.Windows.Forms;
using System.Data.SqlClient;
using System.Drawing;
using ServiceStack;
using ServiceStack.DataAnnotations;
using ServiceStack.Model;
using System.Reflection;
using System.Linq;

#region "FormPlugin"
public class FormPlugin : System.MarshalByRefObject, JiwaFinancials.Jiwa.JiwaApplication.IJiwaFormPlugin
{

    public override object InitializeLifetimeService()
    {
        // returning null here will prevent the lease manager
        // from deleting the Object.
        return null;
    }

    public void SetupBeforeHandlers(JiwaFinancials.Jiwa.JiwaApplication.IJiwaForm JiwaForm, JiwaFinancials.Jiwa.JiwaApplication.Plugin.Plugin Plugin)
    {
    }

    public void Setup(JiwaFinancials.Jiwa.JiwaApplication.IJiwaForm JiwaForm, JiwaFinancials.Jiwa.JiwaApplication.Plugin.Plugin Plugin)
    {
		if(Plugin.Manager.Staff.UserGroupMemberships.Cast<JiwaFinancials.Jiwa.JiwaApplication.JiwaStaff.UserGroupMember>().Any(gm => gm.UserGroup.Name == "Move PO to Another Warehouse"))
		{
			JiwaFinancials.Jiwa.JiwaPurchaseOrdersUI.MainForm purchaseOrderForm = (JiwaFinancials.Jiwa.JiwaPurchaseOrdersUI.MainForm)JiwaForm;
			// Move purchase order to another warehouse
			Infragistics.Win.UltraWinToolbars.ButtonTool movePOButton = new Infragistics.Win.UltraWinToolbars.ButtonTool("Move PO");
	        movePOButton.SharedProps.Caption = "Move PO";
	        movePOButton.SharedProps.ToolTipText = "Move purchase order to another warehouse";
	        purchaseOrderForm.UltraToolbarsManager1.Tools.Add(movePOButton);
			
			Infragistics.Win.UltraWinToolbars.RibbonGroup ribbonGroup = purchaseOrderForm.UltraToolbarsManager1.Ribbon.Tabs["Main"].Groups["Actions"];
	        if (ribbonGroup != null)
	        {
	            ribbonGroup.Tools.AddTool("Move PO");				
				ribbonGroup.Tools["Move PO"].InstanceProps.MinimumSizeOnRibbon = Infragistics.Win.UltraWinToolbars.RibbonToolSize.Normal;
	        }
			
			purchaseOrderForm.UltraToolbarsManager1.ToolClick += purchaseOrderForm_UltraToolbarsManager1_ToolClick;
			purchaseOrderForm.PurchaseOrder.ReadEnd += purchaseOrderForm_PurchaseOrder_ReadEnd;
			purchaseOrderForm.PurchaseOrder.CreateEnd += purchaseOrderForm_PurchaseOrder_CreateEnd;
			purchaseOrderForm.PurchaseOrder.PropertyChanged += purchaseOrderForm_PurchaseOrder_PropertyChanged; 
			purchaseOrderForm.PurchaseOrder.DeserialiseEnd += purchaseOrderForm_PurchaseOrder_DeserialiseEnd; 
			purchaseOrderForm.PurchaseOrder.CopyEnd += purchaseOrderForm_PurchaseOrder_CopyEnd;			
		}
    }
	
	public void EnableOrDisableMovePOButton(JiwaFinancials.Jiwa.JiwaPurchaseOrdersUI.MainForm PurchaseOrderForm)
	{
		PurchaseOrderForm.movePOButton().SharedProps.Enabled = PurchaseOrderForm.PurchaseOrder.ChangeFlag == false
															&& PurchaseOrderForm.PurchaseOrder.OrderSupplierType == JiwaFinancials.Jiwa.JiwaPurchaseOrders.PurchaseOrder.SupplierType.Creditor
															&& PurchaseOrderForm.PurchaseOrder.OrderStatus == JiwaFinancials.Jiwa.JiwaApplication.Entities.PurchaseOrder.Workflow.Status.Sent
									                        && PurchaseOrderForm.PurchaseOrder.SomeDelivered() == false;
	}
	
	#region "Control event handlers"
	private void purchaseOrderForm_UltraToolbarsManager1_ToolClick(object sender, Infragistics.Win.UltraWinToolbars.ToolClickEventArgs e)
    {
		JiwaFinancials.Jiwa.JiwaPurchaseOrdersUI.MainForm purchaseOrderForm = (JiwaFinancials.Jiwa.JiwaPurchaseOrdersUI.MainForm)e.Tool.ToolbarsManager.DockWithinContainer;
		
        if (e.Tool.Key == "Move PO")
		{
			
			bool movablePO = purchaseOrderForm.PurchaseOrder.ChangeFlag == false
						  && purchaseOrderForm.PurchaseOrder.OrderSupplierType == JiwaFinancials.Jiwa.JiwaPurchaseOrders.PurchaseOrder.SupplierType.Creditor
						  && purchaseOrderForm.PurchaseOrder.OrderStatus == JiwaFinancials.Jiwa.JiwaApplication.Entities.PurchaseOrder.Workflow.Status.Sent
                          && purchaseOrderForm.PurchaseOrder.SomeDelivered() == false;

            if (movablePO == false) //initially read order may not disable button and invalid orders may be able to move
            {
                purchaseOrderForm.Manager.DisplayMessage(purchaseOrderForm, "This order is not eligible for moving", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            JiwaFinancials.Jiwa.JiwaApplication.Entities.LogicalWarehouse logicalWarehouse = purchaseOrderForm.Manager.EntityFactory.CreateEntity<JiwaFinancials.Jiwa.JiwaApplication.Entities.LogicalWarehouse>();

			string destinationLogicalWarehouseRecID = SearchWarehouses(purchaseOrderForm, string.Format("IN_Logical.IN_LogicalID <> '{0}'", purchaseOrderForm.PurchaseOrder.LogicalWarehouseResidingIn.IN_LogicalID));

            if (string.IsNullOrWhiteSpace(destinationLogicalWarehouseRecID) == false)
            {
				logicalWarehouse.ReadRecord(destinationLogicalWarehouseRecID);
                if (purchaseOrderForm.Manager.DisplayMessage(purchaseOrderForm, string.Concat("Purchase order will be created in ", logicalWarehouse.ToString(), Environment.NewLine + "Do you want to proceed?"), MessageBoxButtons.YesNo, MessageBoxIcon.Question, MessageBoxDefaultButton.Button1) == DialogResult.Yes)
                {
					JiwaFinancials.Jiwa.JiwaPurchaseOrdersUI.PurchaseOrders movedOrderForm = null;
					var oldLogicalWarehouse = purchaseOrderForm.Manager.CurrentLogicalWarehouse;
					var movedOrderLogicalWarehouse = purchaseOrderForm.Manager.PhysicalWarehouseCollection.FindLogicalWarehouse(logicalWarehouse.IN_LogicalID);
					try
					{
						purchaseOrderForm.Manager.CurrentLogicalWarehouse = movedOrderLogicalWarehouse;

	                    movedOrderForm = purchaseOrderForm.Manager.FormFactory.CreateForm<JiwaFinancials.Jiwa.JiwaPurchaseOrdersUI.PurchaseOrders>(null);
	                    movedOrderForm.InitialReadMode = JiwaFinancials.Jiwa.JiwaApplication.IJiwaNavigable.ReadModes.None;
	                    movedOrderForm.Start();						
					}
					finally
					{
						purchaseOrderForm.Manager.CurrentLogicalWarehouse = oldLogicalWarehouse;
					}
					
                    var sourceOrder = purchaseOrderForm.PurchaseOrder;
                    var movedOrder = movedOrderForm.PurchaseOrder;
					
					JiwaFinancials.Jiwa.JiwaServiceModel.PurchaseOrders.PurchaseOrder sourcePODTO = sourceOrder.DTO_Serialise();
					sourcePODTO.PurchaseOrderID = null;
					sourcePODTO.LogicalWarehouseResidingInRecID = logicalWarehouse.IN_LogicalID;
					sourcePODTO.LogicalWarehouseResidingInDescription = logicalWarehouse.Description;
					sourcePODTO.PhysicalWarehouseResidingInRecID = logicalWarehouse.PhysicalWarehouse.IN_PhysicalID;
					sourcePODTO.PhysicalWarehouseResidingInDescription = logicalWarehouse.PhysicalWarehouse.Description;
					
					sourcePODTO.Lines.ForEach(x => x.PurchaseOrderLineID = null);
					sourcePODTO.Notes.ForEach(x => x.NoteID = null);
					sourcePODTO.Documents.ForEach(x => x.DocumentID = null);
					sourcePODTO.OrderNo = null;

					//We have to work around PurchaseOrder.Lines.Deserialise crashing if confronted with a comment line.
					
					//Get a copy of the comments
					var commentLines = new List<JiwaFinancials.Jiwa.JiwaServiceModel.PurchaseOrders.PurchaseOrderLine>();
					
					foreach(JiwaFinancials.Jiwa.JiwaServiceModel.PurchaseOrders.PurchaseOrderLine dtoLine in sourcePODTO.Lines)
					{
						if(dtoLine.PurchaseOrderLineType == JiwaFinancials.Jiwa.JiwaServiceModel.PurchaseOrders.PurchaseOrderLine.OrderLineType.Comment)
						{
							JiwaFinancials.Jiwa.JiwaServiceModel.PurchaseOrders.PurchaseOrderLine commentLine = new JiwaFinancials.Jiwa.JiwaServiceModel.PurchaseOrders.PurchaseOrderLine();
							commentLine.PurchaseOrderLineType = JiwaFinancials.Jiwa.JiwaServiceModel.PurchaseOrders.PurchaseOrderLine.OrderLineType.Comment;
							commentLine.HistoryText_Comment = dtoLine.HistoryText_Comment;
							commentLine.ItemNo = dtoLine.ItemNo;
							
							foreach(JiwaFinancials.Jiwa.JiwaServiceModel.CustomFields.CustomFieldValue dtoLineCustomFieldValue in dtoLine.CustomFieldValues)
							{
								JiwaFinancials.Jiwa.JiwaServiceModel.CustomFields.CustomFieldValue commentLineCustomFieldValue = new JiwaFinancials.Jiwa.JiwaServiceModel.CustomFields.CustomFieldValue();
								commentLineCustomFieldValue.SettingID = dtoLineCustomFieldValue.SettingID;
								commentLineCustomFieldValue.Contents = dtoLineCustomFieldValue.Contents;
								commentLine.CustomFieldValues.Add(commentLineCustomFieldValue);
							}
							
							commentLines.Add(commentLine);
						}
					}
					
					//remove the comments
					sourcePODTO.Lines.RemoveAll(x => x.PurchaseOrderLineType == JiwaFinancials.Jiwa.JiwaServiceModel.PurchaseOrders.PurchaseOrderLine.OrderLineType.Comment);
							
					try
					{
						movedOrderForm.AboutToAskMakeThisSupplierTheDefault += movedOrderForm_AboutToAskMakeThisSupplierTheDefault;					
						movedOrderForm.AboutToAskItemAlreadyOnOrder += movedOrderForm_AboutToAskItemAlreadyOnOrder;					
						movedOrderForm.AboutToAskItemNotOrderedFromSupplier += movedOrderForm_AboutToAskItemNotOrderedFromSupplier;					
						movedOrder.DTO_Deserialise(sourcePODTO);
					}
					finally
					{
						movedOrderForm.AboutToAskMakeThisSupplierTheDefault -= movedOrderForm_AboutToAskMakeThisSupplierTheDefault;
						movedOrderForm.AboutToAskItemAlreadyOnOrder -= movedOrderForm_AboutToAskItemAlreadyOnOrder;
						movedOrderForm.AboutToAskItemNotOrderedFromSupplier -= movedOrderForm_AboutToAskItemNotOrderedFromSupplier;
					}
					
					
					//Add in the comments
					foreach(JiwaFinancials.Jiwa.JiwaServiceModel.PurchaseOrders.PurchaseOrderLine commentLine in commentLines)
					{
						object newKey = null;
						movedOrder.Lines.AddCommentLine(commentLine.HistoryText_Comment, ref newKey, (int)commentLine.ItemNo);
						JiwaFinancials.Jiwa.JiwaPurchaseOrders.Line newLine = movedOrder.Lines[newKey.ToString()];
						foreach(JiwaFinancials.Jiwa.JiwaApplication.CustomFields.CustomFieldValue customFieldValue in newLine.CustomFieldValues)
						{
							foreach(JiwaFinancials.Jiwa.JiwaServiceModel.CustomFields.CustomFieldValue customFieldValueDTO in commentLine.CustomFieldValues)
							{
								if(customFieldValue.CustomField.PluginCustomField.SettingID == customFieldValueDTO.SettingID)
								{
									customFieldValue.Contents = customFieldValueDTO.Contents;
									break;
								}
							}
						}
					}

		            MethodInfo dynMethodReadRecord = movedOrder.ShippingAddress.GetType().GetMethod("ReadRecord", BindingFlags.NonPublic | BindingFlags.Instance);
		            dynMethodReadRecord.Invoke(movedOrder.ShippingAddress, new object[] { movedOrder.LogicalWarehouseResidingIn.PhysicalWarehouse.IN_PhysicalID });	
					string originalSourceOrderNo = sourceOrder.OrderNo;

					sourceOrder.CloseOrder();
					UpdateOrderNo(sourceOrder.Manager, sourceOrder.OrderID, string.Format("{0}-{1}", sourceOrder.OrderNo, "Moved"));
					sourceOrder.Read(sourceOrder.OrderID);
					
					movedOrder.OrderNo = originalSourceOrderNo; //This gets overwritten by Save but not before being used for the journal description.
					movedOrder.Save();
					UpdateOrderNo(movedOrder.Manager, movedOrder.OrderID, originalSourceOrderNo);
					movedOrder.Read(movedOrder.OrderID);
                    
                }
            }
		}
    }	
	#endregion
	
	#region "Business logic event handlers"	
	public void movedOrderForm_AboutToAskMakeThisSupplierTheDefault(object sender, ref bool MakeDefault, ref bool Cancel)
	{
		Cancel = true;
	}
	
	public void movedOrderForm_AboutToAskItemAlreadyOnOrder(string PartNo, ref bool Cancel)
	{
		Cancel = true;
	}
	
	public void movedOrderForm_AboutToAskItemNotOrderedFromSupplier(string PartNo, ref bool Cancel)
	{
		Cancel = true;
	}	
	
	public void purchaseOrderForm_PurchaseOrder_ReadEnd(object sender, System.EventArgs e)
	{
		JiwaFinancials.Jiwa.JiwaPurchaseOrders.PurchaseOrder purchaseOrder = (JiwaFinancials.Jiwa.JiwaPurchaseOrders.PurchaseOrder)sender;
		JiwaFinancials.Jiwa.JiwaPurchaseOrdersUI.MainForm purchaseOrderForm = (JiwaFinancials.Jiwa.JiwaPurchaseOrdersUI.MainForm)purchaseOrder.Client;
		EnableOrDisableMovePOButton(purchaseOrderForm);
	}
	
	public void purchaseOrderForm_PurchaseOrder_CreateEnd(object sender, System.EventArgs e)
	{
		JiwaFinancials.Jiwa.JiwaPurchaseOrders.PurchaseOrder purchaseOrder = (JiwaFinancials.Jiwa.JiwaPurchaseOrders.PurchaseOrder)sender;
		JiwaFinancials.Jiwa.JiwaPurchaseOrdersUI.MainForm purchaseOrderForm = (JiwaFinancials.Jiwa.JiwaPurchaseOrdersUI.MainForm)purchaseOrder.Client;
		EnableOrDisableMovePOButton(purchaseOrderForm);		
	}
	
	public void purchaseOrderForm_PurchaseOrder_PropertyChanged(object sender, System.ComponentModel.PropertyChangedEventArgs e)
	{
		JiwaFinancials.Jiwa.JiwaPurchaseOrders.PurchaseOrder purchaseOrder = (JiwaFinancials.Jiwa.JiwaPurchaseOrders.PurchaseOrder)sender;
		JiwaFinancials.Jiwa.JiwaPurchaseOrdersUI.MainForm purchaseOrderForm = (JiwaFinancials.Jiwa.JiwaPurchaseOrdersUI.MainForm)purchaseOrder.Client;
		EnableOrDisableMovePOButton(purchaseOrderForm);		
	}
	
	public void purchaseOrderForm_PurchaseOrder_DeserialiseEnd(object sender, System.EventArgs e, object poco)
	{
		JiwaFinancials.Jiwa.JiwaPurchaseOrders.PurchaseOrder purchaseOrder = (JiwaFinancials.Jiwa.JiwaPurchaseOrders.PurchaseOrder)sender;
		JiwaFinancials.Jiwa.JiwaPurchaseOrdersUI.MainForm purchaseOrderForm = (JiwaFinancials.Jiwa.JiwaPurchaseOrdersUI.MainForm)purchaseOrder.Client;
		EnableOrDisableMovePOButton(purchaseOrderForm);		
	}
	
	public void purchaseOrderForm_PurchaseOrder_CopyEnd(object sender, System.EventArgs e)
	{
		JiwaFinancials.Jiwa.JiwaPurchaseOrders.PurchaseOrder purchaseOrder = (JiwaFinancials.Jiwa.JiwaPurchaseOrders.PurchaseOrder)sender;
		JiwaFinancials.Jiwa.JiwaPurchaseOrdersUI.MainForm purchaseOrderForm = (JiwaFinancials.Jiwa.JiwaPurchaseOrdersUI.MainForm)purchaseOrder.Client;
		EnableOrDisableMovePOButton(purchaseOrderForm);		
	}	
	#endregion
	
	#region "Search"
	public string SearchWarehouses(JiwaFinancials.Jiwa.JiwaApplication.IJiwaForm OwnerForm, string FilterString)
	{
        OwnerForm.Manager.Search.Clear();
		JiwaFinancials.Jiwa.JiwaApplication.JiwaSearch.clsSearch.SearchModes searchMode = JiwaFinancials.Jiwa.JiwaApplication.JiwaSearch.clsSearch.SearchModes.jswLogicalWarehouse;
        OwnerForm.Manager.Search.SetDefaultSearch(ref searchMode);
        OwnerForm.Manager.Search.UsePinBoard = false;
		
		if(!string.IsNullOrWhiteSpace(FilterString))
		{
			foreach(JiwaFinancials.Jiwa.JiwaApplication.JiwaSearch.SearchOption searchOption in OwnerForm.Manager.Search.Options)
			{
				if(searchOption.SQLStr.ToLower().Contains("where"))
				{				
					searchOption.SQLStr += " AND ";
				}
				else
				{
					searchOption.SQLStr += " WHERE ";
				}
				
				searchOption.SQLStr += FilterString;
			}			
		}		

        if (OwnerForm.Manager.Search.Show(OwnerForm.Form) == DialogResult.OK)
        {
            if (OwnerForm.Manager.Search.Results.Count > 0)
			{
				return OwnerForm.Manager.Search.Result(1).Fields[1].FieldValue.ToString();
			}
        }
		
		return "";
	}	
	#endregion
	
	#region "Misc"
	public void UpdateOrderNo(JiwaFinancials.Jiwa.JiwaApplication.Manager Manager, string OrderID, string NewOrderNo)
	{
        System.Data.SqlClient.SqlParameter SQLParam = null;
		var db = Manager.Database;

        string SQL = @"UPDATE PO_Main SET OrderNo = @OrderNo WHERE OrderID = @OrderID";

        using (System.Data.SqlClient.SqlCommand SQLCmd = new System.Data.SqlClient.SqlCommand(SQL, db.SQLConnection, db.SQLTransaction))
        {			
            SQLParam = new SqlParameter("@OrderID", System.Data.SqlDbType.Char);
            SQLParam.Value = OrderID;
            SQLCmd.Parameters.Add(SQLParam);

            SQLParam = new SqlParameter("@OrderNo", System.Data.SqlDbType.VarChar);
            SQLParam.Value = NewOrderNo;
            SQLCmd.Parameters.Add(SQLParam);

            if(SQLCmd.ExecuteNonQuery() != 1)
			{
                throw new JiwaFinancials.Jiwa.JiwaApplication.Exceptions.ConcurrencyConflictException(string.Format("Unable to update purchase order no. to {1}", NewOrderNo) );
			}
        }
		
	}		
	#endregion
}
#endregion

#region "Extension Methods"
public static class ExtensionMethods
{
	public static bool SomeDelivered(this JiwaFinancials.Jiwa.JiwaPurchaseOrders.PurchaseOrder PurchaseOrder)
	{
		foreach(JiwaFinancials.Jiwa.JiwaPurchaseOrders.Line line in PurchaseOrder.Lines)
		{
			if(line.Delivered > 0)
			{
				return true;
			}
		}
		
		return false;
	}
	
	public static Infragistics.Win.UltraWinToolbars.ButtonTool movePOButton(this JiwaFinancials.Jiwa.JiwaPurchaseOrdersUI.MainForm PurchaseOrderForm)
	{		
		return PurchaseOrderForm.UltraToolbarsManager1.Tools["Move PO"] as Infragistics.Win.UltraWinToolbars.ButtonTool;
	}
}
#endregion
